insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"classic-1","prompt":"What most gives a person a sense of ownership over their own body?","theme":"Body & Autonomy","answers":["Being able to say no","Choosing their own care","Choosing their own pace","Choosing how they present themselves"],"sort_order":1,"version":"classic"},{"id":"classic-2","prompt":"Name an everyday situation that can make someone feel less in control of their body.","theme":"Body & Autonomy","answers":["A rigid schedule","Too little rest","Constant monitoring","Pressure to stay productive"],"sort_order":2,"version":"classic"},{"id":"classic-3","prompt":"What makes self-determination feel most real?","theme":"Body & Autonomy","answers":["Freedom to refuse","Freedom to change your mind","Freedom to set boundaries","Freedom to ask for support"],"sort_order":3,"version":"classic"},{"id":"classic-4","prompt":"Name a body signal people often ignore when life gets too busy.","theme":"Body & Autonomy","answers":["Fatigue","Hunger","Tension","Need for movement"],"sort_order":4,"version":"classic"},{"id":"classic-5","prompt":"What can make a personal bodily choice feel less free?","theme":"Body & Autonomy","answers":["Money pressure","Social pressure","Work pressure","Expert authority"],"sort_order":5,"version":"classic"},{"id":"classic-6","prompt":"Which personal boundary can be hardest to defend?","theme":"Body & Autonomy","answers":["Your time","Your personal space","Your privacy","Your need for rest"],"sort_order":6,"version":"classic"},{"id":"classic-7","prompt":"Name a sign that daily life respects human limits.","theme":"Body & Autonomy","answers":["Enough sleep","Flexible time","Quiet breaks","Unhurried care"],"sort_order":7,"version":"classic"},{"id":"classic-8","prompt":"What makes a person feel that their dignity is being respected?","theme":"Body & Autonomy","answers":["Being listened to","Being asked for consent","Being given enough time","Being trusted"],"sort_order":8,"version":"classic"},{"id":"classic-9","prompt":"How might freedom be felt physically?","theme":"Body & Autonomy","answers":["Relaxed breathing","Steady energy","Less tension","Easier movement"],"sort_order":9,"version":"classic"},{"id":"classic-10","prompt":"What basic need should come before constant productivity?","theme":"Body & Autonomy","answers":["Rest","Nourishment","Movement","Connection"],"sort_order":10,"version":"classic"},{"id":"classic-11","prompt":"Name something that can make a person feel treated like a tool instead of a human.","theme":"Body & Autonomy","answers":["Output being measured","Discomfort being ignored","Breaks being timed","Appearance being judged"],"sort_order":11,"version":"classic"},{"id":"classic-12","prompt":"What can help someone feel they have reclaimed part of their day?","theme":"Body & Autonomy","answers":["Choosing their pace","Taking real rest","Moving freely","Disconnecting for a while"],"sort_order":12,"version":"classic"},{"id":"classic-13","prompt":"What most supports bodily autonomy in everyday life?","theme":"Body & Autonomy","answers":["Good information","Enough time","Enough resources","Supportive people"],"sort_order":13,"version":"classic"},{"id":"classic-14","prompt":"Why can a personal choice also be a social issue?","theme":"Body & Autonomy","answers":["Options depend on cost","Family duties shape options","Work rules shape options","Culture shapes expectations"],"sort_order":14,"version":"classic"},{"id":"classic-15","prompt":"What is a strong sign that an institution respects bodily autonomy?","theme":"Body & Autonomy","answers":["Clear consent","Accessible choices","Privacy","A real right to refuse"],"sort_order":15,"version":"classic"},{"id":"classic-16","prompt":"What kind of knowledge about the body do people tend to trust most?","theme":"Body & Autonomy","answers":["Lived experience","Repeated body signals","Personal limits","Informed professional advice"],"sort_order":16,"version":"classic"},{"id":"classic-17","prompt":"How does the body commonly push back against overwork?","theme":"Body & Autonomy","answers":["Exhaustion","Loss of focus","Irritability","Need for sleep"],"sort_order":17,"version":"classic"},{"id":"classic-18","prompt":"Name a small freedom people may underestimate.","theme":"Body & Autonomy","answers":["Choosing when to rest","Choosing how to move","Choosing what to wear","Choosing when to be alone"],"sort_order":18,"version":"classic"},{"id":"classic-19","prompt":"What can quietly reduce a person''s sense of autonomy?","theme":"Body & Autonomy","answers":["Rigid scheduling","Constant ranking","Constant tracking","Constant comparison"],"sort_order":19,"version":"classic"},{"id":"classic-20","prompt":"What best describes a healthy relationship with your own body?","theme":"Body & Autonomy","answers":["Listening","Patience","Curiosity","Compassion"],"sort_order":20,"version":"classic"},{"id":"classic-21","prompt":"What makes work feel more human?","theme":"Work, Time & Productivity","answers":["Control over pace","Meaningful tasks","Enough time","Supportive people"],"sort_order":21,"version":"classic"},{"id":"classic-22","prompt":"What makes work start to feel mechanical?","theme":"Work, Time & Productivity","answers":["Repeated tasks","Constant timers","No real decisions","Nonstop monitoring"],"sort_order":22,"version":"classic"},{"id":"classic-23","prompt":"What is the hardest part of being overworked?","theme":"Work, Time & Productivity","answers":["Losing personal time","Losing connection with others","Constant fatigue","No mental space"],"sort_order":23,"version":"classic"},{"id":"classic-24","prompt":"What is a better sign of good work than simply doing more?","theme":"Work, Time & Productivity","answers":["Quality","Sustainability","Usefulness","Learning"],"sort_order":24,"version":"classic"},{"id":"classic-25","prompt":"Besides money, what do people most need from work?","theme":"Work, Time & Productivity","answers":["Respect","Purpose","Control","Belonging"],"sort_order":25,"version":"classic"},{"id":"classic-26","prompt":"How does workplace pressure most often show up?","theme":"Work, Time & Productivity","answers":["Pressure to go faster","Pressure to be always available","Pressure to hit targets","Pressure to monitor yourself"],"sort_order":26,"version":"classic"},{"id":"classic-27","prompt":"What makes a worker feel more free?","theme":"Work, Time & Productivity","answers":["Choosing how to work","Choosing their pace","Choosing when to pause","Having a real voice"],"sort_order":27,"version":"classic"},{"id":"classic-28","prompt":"What can drain the life out of a job fastest?","theme":"Work, Time & Productivity","answers":["Unpredictability","Repetition","Surveillance","Meaningless tasks"],"sort_order":28,"version":"classic"},{"id":"classic-29","prompt":"Modern life often treats time as what?","theme":"Work, Time & Productivity","answers":["Money","A schedule","A target","A resource"],"sort_order":29,"version":"classic"},{"id":"classic-30","prompt":"What kind of break is most restorative during a long day?","theme":"Work, Time & Productivity","answers":["Quiet time","A little movement","A good conversation","Time outdoors"],"sort_order":30,"version":"classic"},{"id":"classic-31","prompt":"What makes a job feel worth staying in?","theme":"Work, Time & Productivity","answers":["Fair pay","Manageable hours","Respect","Autonomy"],"sort_order":31,"version":"classic"},{"id":"classic-32","prompt":"If automation improves work, what should it reduce first?","theme":"Work, Time & Productivity","answers":["Repetitive tasks","Dangerous tasks","Administrative tasks","After-hours tasks"],"sort_order":32,"version":"classic"},{"id":"classic-33","prompt":"What is most at risk when efficiency becomes the main value?","theme":"Work, Time & Productivity","answers":["People get rushed","Care gets reduced","Creativity gets reduced","Rest disappears"],"sort_order":33,"version":"classic"},{"id":"classic-34","prompt":"What would make the future of work feel more humane?","theme":"Work, Time & Productivity","answers":["Shorter workdays","Flexible hours","Shared decisions","Stable security"],"sort_order":34,"version":"classic"},{"id":"classic-35","prompt":"Name a kind of work that often stays invisible.","theme":"Work, Time & Productivity","answers":["Planning","Emotional support","Caregiving","Household coordination"],"sort_order":35,"version":"classic"},{"id":"classic-36","prompt":"What do people often confuse with being busy?","theme":"Work, Time & Productivity","answers":["Being useful","Being responsible","Being important","Being productive"],"sort_order":36,"version":"classic"},{"id":"classic-37","prompt":"What can create burnout fastest?","theme":"Work, Time & Productivity","answers":["No control","No rest","No recognition","No boundaries"],"sort_order":37,"version":"classic"},{"id":"classic-38","prompt":"What is the clearest sign that a job respects the body?","theme":"Work, Time & Productivity","answers":["Real breaks","A safe pace","Reasonable hours","Comfortable working conditions"],"sort_order":38,"version":"classic"},{"id":"classic-39","prompt":"Who does your time feel like it belongs to most on a normal weekday?","theme":"Work, Time & Productivity","answers":["Yourself","Your family","Your school or workplace","Your community"],"sort_order":39,"version":"classic"},{"id":"classic-40","prompt":"What activity best helps someone recover after a demanding day?","theme":"Work, Time & Productivity","answers":["Sleep","A walk","Talking with someone","A creative hobby"],"sort_order":40,"version":"classic"},{"id":"classic-41","prompt":"Name a kind of care that often goes unnoticed.","theme":"Care, Family & Everyday Support","answers":["Listening","Planning","Cleaning","Reminding"],"sort_order":41,"version":"classic"},{"id":"classic-42","prompt":"What makes caregiving hardest?","theme":"Care, Family & Everyday Support","answers":["Not enough time","Not enough money","Not enough help","Not enough recognition"],"sort_order":42,"version":"classic"},{"id":"classic-43","prompt":"What makes support inside a family feel fair?","theme":"Care, Family & Everyday Support","answers":["Shared tasks","Shared decisions","Shared time","Shared responsibility"],"sort_order":43,"version":"classic"},{"id":"classic-44","prompt":"What resource matters most when caring for someone?","theme":"Care, Family & Everyday Support","answers":["Time","Patience","Money","Community"],"sort_order":44,"version":"classic"},{"id":"classic-45","prompt":"What does society rely on heavily but often undervalue?","theme":"Care, Family & Everyday Support","answers":["Child care","Elder care","Emotional support","Household work"],"sort_order":45,"version":"classic"},{"id":"classic-46","prompt":"What is the strongest form of everyday care?","theme":"Care, Family & Everyday Support","answers":["Showing up","Checking in","Helping practically","Making time"],"sort_order":46,"version":"classic"},{"id":"classic-47","prompt":"What makes caring for a family feel more like a choice than an obligation?","theme":"Care, Family & Everyday Support","answers":["Support","Resources","Flexibility","Respect"],"sort_order":47,"version":"classic"},{"id":"classic-48","prompt":"What should communities share more often?","theme":"Care, Family & Everyday Support","answers":["Child care","Meals","Transportation","Useful information"],"sort_order":48,"version":"classic"},{"id":"classic-49","prompt":"What grows when all care is pushed onto individuals or families?","theme":"Care, Family & Everyday Support","answers":["Exhaustion","Isolation","Money pressure","Unequal roles"],"sort_order":49,"version":"classic"},{"id":"classic-50","prompt":"What support helps new parents or caregivers most?","theme":"Care, Family & Everyday Support","answers":["Paid time off","Affordable care","Nearby help","Flexible schedules"],"sort_order":50,"version":"classic"}]'::jsonb) r;